using System.Collections;
using System.Collections.Generic;
using TMPro;
using UnityEngine;

// Names are deterministic per spawn identity; no personal data or network lookup.
public sealed class GridShiftCitizen:MonoBehaviour {
 static readonly string[] first={"Alex","Bruno","Camila","Diego","Elisa","Felipe","Gabriela","Hugo","Isabela","João","Lara","Marcos","Nina","Otávio","Paula","Rafael","Sofia","Tiago","Valéria","Yuri"};
 static readonly string[] last={"Lima","Silva","Costa","Rocha","Dias","Moraes","Santos","Alves","Souza","Pereira"};
 public static int StableIndex(string id,int count){unchecked{uint hash=2166136261;foreach(char c in id)hash=(hash^c)*16777619;return count>0?(int)(hash%(uint)count):0;}}
 public static string NameFor(string id)=>first[StableIndex(id,first.Length)]+" "+last[StableIndex(id+"surname",last.Length)];
 public string Nickname{get;private set;}[SerializeField]TMP_Text nameplate;PedestrianAgent agent;[SerializeField]GridShiftWorldAction action;float labelRefresh,alpha=1;bool down;float socialUntil;
 public void AuthorScene(){MakeNameplate();nameplate.text="Nome do NPC";action=GridShiftWorldAction.Create(transform,"Conversar",Vector3.zero,null,"citizen-talk");action.focusOffset=Vector3.up*1.1f;action.focusSize=new Vector3(.65f,1.7f,.65f);action.sceneAuthored=true;}
 void MakeNameplate(){if(nameplate!=null)return;var label=new GameObject("Citizen name",typeof(TextMeshPro));label.transform.SetParent(transform,false);label.transform.localPosition=new Vector3(0,2.12f,0);nameplate=label.GetComponent<TextMeshPro>();nameplate.fontSize=1.5f;nameplate.alignment=TextAlignmentOptions.Center;nameplate.rectTransform.sizeDelta=new Vector2(3,.35f);nameplate.color=new Color(.9f,.95f,1);}
 void Start(){agent=GetComponent<PedestrianAgent>();Nickname=NameFor(gameObject.name+transform.position.ToString("F2"));MakeNameplate();nameplate.text=Nickname;action=GridShiftWorldAction.Create(transform,"Conversar com "+Nickname,Vector3.zero,Talk,"citizen-talk");action.title="Conversar com "+Nickname;if(!action.sceneAuthored){action.focusOffset=Vector3.up*1.1f;action.focusSize=new Vector3(.65f,1.7f,.65f);}action.available=()=>!down&&(agent==null||agent.CurrentActivity!=PedestrianAgent.Activity.Crossing);}
 void LateUpdate(){var camera=GridShiftViewCache.Camera;if(nameplate==null||camera==null)return;if(Time.unscaledTime>=labelRefresh){labelRefresh=Time.unscaledTime+.15f;float distance=Vector3.Distance(camera.transform.position,transform.position);bool show=!down&&distance<18&&!(WorldSession.Instance?.InInterior??false);if(nameplate.gameObject.activeSelf!=show)nameplate.gameObject.SetActive(show);alpha=Mathf.Clamp01((18-distance)/5);nameplate.alpha=alpha;}if(nameplate.gameObject.activeSelf)nameplate.transform.rotation=camera.transform.rotation;}

 public int Warmth{get;private set;}public void React(int topic){Warmth=Mathf.Clamp(Warmth+(topic==7?-1:topic==8?-2:topic==4||topic==9?1:0),-3,3);}
 public void PauseConversation(bool paused){if(agent!=null)agent.DialoguePaused=paused;if(paused){var player=InteractionFocus.PlayerFor(this);if(player!=null){var direction=Vector3.ProjectOnPlane(player.transform.position-transform.position,Vector3.up);if(direction.sqrMagnitude>.01f)transform.rotation=Quaternion.LookRotation(direction);}}}
 bool Talk(PlayerMovement p){if(down||Time.time<socialUntil||agent!=null&&agent.CurrentActivity==PedestrianAgent.Activity.Crossing)return false;socialUntil=Time.time+1;GridShiftCampaignUI.Instance.OpenCitizen(this,p);return true;}
 public bool Strike(Vector3 velocity){if(down||velocity.magnitude<2)return false;GridShiftCampaignUI.Instance?.CloseCitizen(this);down=true;StartCoroutine(Fall(velocity));return true;}
 struct Pose{public Transform bone;public Vector3 position;public Quaternion rotation;}
 IEnumerator Fall(Vector3 velocity){
  bool external=agent!=null&&agent.ExternalControl;if(agent!=null){agent.ExternalControl=true;agent.enabled=false;}var root=GetComponent<Rigidbody>();var rootCollider=GetComponent<CapsuleCollider>();if(rootCollider!=null)rootCollider.enabled=false;var animator=GetComponentInChildren<Animator>();var poses=new List<Pose>();var bodies=new List<Rigidbody>();var joints=new List<CharacterJoint>();var colliders=new List<Collider>();Transform hip=null;
  if(animator!=null&&animator.isHuman){hip=animator.GetBoneTransform(HumanBodyBones.Hips);foreach(var bone in new[]{HumanBodyBones.Hips,HumanBodyBones.Spine,HumanBodyBones.Chest,HumanBodyBones.Head,HumanBodyBones.LeftUpperArm,HumanBodyBones.LeftLowerArm,HumanBodyBones.RightUpperArm,HumanBodyBones.RightLowerArm,HumanBodyBones.LeftUpperLeg,HumanBodyBones.LeftLowerLeg,HumanBodyBones.RightUpperLeg,HumanBodyBones.RightLowerLeg}){var t=animator.GetBoneTransform(bone);if(t==null)continue;poses.Add(new Pose{bone=t,position=t.localPosition,rotation=t.localRotation});var rb=t.GetComponent<Rigidbody>();if(rb==null)rb=t.gameObject.AddComponent<Rigidbody>();rb.mass=bone==HumanBodyBones.Hips?12:4;rb.isKinematic=false;rb.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;rb.linearDamping=.2f;rb.angularDamping=1;var c=t.gameObject.AddComponent<CapsuleCollider>();c.radius=bone==HumanBodyBones.Head?.12f:.085f;c.height=bone==HumanBodyBones.Hips?.25f:.3f;c.direction=1;colliders.Add(c);bodies.Add(rb);}
   animator.enabled=false;
   foreach(var rb in bodies){var parent=rb.transform.parent;while(parent!=null&&parent!=transform&&parent.GetComponent<Rigidbody>()==null)parent=parent.parent;var connected=parent!=null&&parent!=transform?parent.GetComponent<Rigidbody>():null;if(connected!=null){var joint=rb.gameObject.AddComponent<CharacterJoint>();joint.connectedBody=connected;joint.enablePreprocessing=false;joint.enableProjection=true;joint.lowTwistLimit=new SoftJointLimit{limit=-25};joint.highTwistLimit=new SoftJointLimit{limit=25};joint.swing1Limit=new SoftJointLimit{limit=40};joint.swing2Limit=new SoftJointLimit{limit=30};joints.Add(joint);}rb.AddForce(Vector3.ClampMagnitude(velocity,12)*.35f+Vector3.up,ForceMode.VelocityChange);}
   for(int i=0;i<colliders.Count;i++)for(int j=i+1;j<colliders.Count;j++)Physics.IgnoreCollision(colliders[i],colliders[j]);
  }else{if(root!=null){root.isKinematic=false;root.useGravity=true;root.constraints=RigidbodyConstraints.None;if(rootCollider!=null)rootCollider.enabled=true;root.AddForce(Vector3.ClampMagnitude(velocity,10)*.4f+Vector3.up,ForceMode.VelocityChange);}}
  yield return new WaitForSeconds(7);
  // Keep the body physical while a vehicle still covers it. Vehicle roofs are not ground.
  Vector3 stand=Vector3.zero;bool safe=false;while(!safe){var resting=hip!=null?hip.position:transform.position;var hits=Physics.RaycastAll(resting+Vector3.up*1.5f,Vector3.down,12,~(1<<9),QueryTriggerInteraction.Ignore);System.Array.Sort(hits,(a,b)=>a.distance.CompareTo(b.distance));foreach(var floor in hits){var fc=floor.collider;if(fc.transform.IsChildOf(transform)||fc.attachedRigidbody!=null||fc.GetComponentInParent<TrafficCar>()!=null||fc.GetComponentInParent<GridShiftPlayerVan>()!=null||floor.normal.y<.85f)continue;stand=floor.point+Vector3.up*.03f;safe=true;foreach(var c in Physics.OverlapCapsule(stand+Vector3.up*.35f,stand+Vector3.up*1.45f,.3f,~(1<<9),QueryTriggerInteraction.Ignore))if(!c.transform.IsChildOf(transform)){safe=false;break;}break;}if(!safe)yield return new WaitForSeconds(.3f);}
  foreach(var joint in joints)Destroy(joint);foreach(var c in colliders)Destroy(c);foreach(var rb in bodies)Destroy(rb);yield return null;
  if(root!=null){root.isKinematic=true;root.useGravity=false;root.constraints=RigidbodyConstraints.None;root.position=stand;root.rotation=Quaternion.Euler(0,transform.eulerAngles.y,0);}transform.SetPositionAndRotation(stand,Quaternion.Euler(0,transform.eulerAngles.y,0));  foreach(var pose in poses)if(pose.bone!=null){pose.bone.localPosition=pose.position;pose.bone.localRotation=pose.rotation;}if(animator!=null)animator.enabled=true;if(rootCollider!=null)rootCollider.enabled=true;down=false;if(agent!=null){agent.ExternalControl=external;agent.enabled=true;}
 }
 void OnDestroy(){GridShiftCampaignUI.Instance?.CloseCitizen(this);if(nameplate!=null)Destroy(nameplate.gameObject);}
}

